baseid = 221040000
dungeonid = 221040001

function enter(pi)
    if (pi.getMapId() == baseid) then
        if (pi.getParty() ~= nil) then
            if pi.isLeader() then
                if (pi.getPlayerCount(dungeonid) == 0) then
                    pi.warpParty(dungeonid)
                    do return end
                end
            else
                pi.playerMessage(5, "你不是隊長.")
            end
        else
            if (pi.getPlayerCount(dungeonid) == 0) then
                pi.warp(dungeonid)
                do return end
            end
        end
        pi.playerMessage(5, "All of the Mini-Dungeons are in use right now, please try again later.")
    else
        pi.playPortalSE()
        pi.warp(baseid, "MD00")
    end
end
